(()=>{
const M=CivicModel,root=$('#civic-section');
let feed={topics:[],results:{}},feedError='',editing=null,progress=null,activeTopic=localStorage.getItem('civic-selected-topic')||null,landmarks={};
const option=(value,label=value)=>`<option value="${esc(value)}">${esc(label)}</option>`;
$('#civic-scope').innerHTML=option('全部')+M.scopes.map(s=>option(s)).join('');
$('#civic-scope').value=['全部',...M.scopes].includes(localStorage.getItem('civic-selected-scope'))?localStorage.getItem('civic-selected-scope'):'臺北市';
$('#civic-edit-scope').innerHTML=M.scopes.map(s=>option(s)).join('');
let deletedFallbacks;try{deletedFallbacks=new Set(JSON.parse(localStorage.getItem('civic-deleted-topics')||'[]'))}catch{deletedFallbacks=new Set()}
const topics=()=>[...new Map([...(baseIssues===null?(feed.topics||[]).filter(i=>!deletedFallbacks.has(i.id)):[]),...issues.filter(i=>i.kind==='civic')].map(i=>[i.id,i])).values()];
function editable(id){let item=issues.find(i=>i.id===id);if(!item){item=structuredClone(topics().find(i=>i.id===id));if(!item)throw Error('找不到議題');issues.push(item)}return item}
const relationHtml=(topic,entry)=>{if(!entry.criterionId&&entry.label!=='進度紀錄')return '';const c=(topic.criteria||[]).find(c=>entry.criterionId?c.id===entry.criterionId:c.text===entry.title);return `<p class="civic-entry-relation">關聯指標：${esc(c?.text||entry.criterionText||entry.title||'早期指標紀錄')}${entry.criterionId&&!c?'（已移除）':''}</p>`};
const linksHtml=links=>(links||[]).filter(l=>M.safeUrl(l.url)).map(l=>`<a class="source-link" href="${esc(M.safeUrl(l.url))}" target="_blank" rel="noopener noreferrer">↗ ${esc(l.title||l.url)}</a>`).join('');
window.renderCivic=function(){
 const opened=new Set([...root.querySelectorAll('details[open]')].map(d=>d.dataset.detail));
 const q=M.normalize($('#civic-search').value),scope=$('#civic-scope').value;
 const list=topics().filter(i=>(scope==='全部'||i.scope===scope)&&M.normalize(i.name+' '+i.scope+' '+i.keys.join(' ')+' '+i.note).includes(q));
 if(!list.some(i=>i.id===activeTopic))activeTopic=list[0]?.id||null;
 if(activeTopic)localStorage.setItem('civic-selected-topic',activeTopic);
 $('#civic-scope-title').textContent=scope==='全部'?'全部議題':scope;
 $('#civic-city-tabs').innerHTML=['中央',...M.scopes.filter(city=>city!=='中央'&&city!=='國際'),'國際'].map(city=>`<button data-civic-city="${esc(city)}" class="${city===scope?'active':''}" aria-pressed="${city===scope}">${esc(city)}</button>`).join('');
 requestAnimationFrame(ensureScopeVisible);
 $('#civic-topic-tabs').innerHTML=list.map(i=>`<button class="${i.id===activeTopic?'active':''}" data-civic-topic="${esc(i.id)}" aria-pressed="${i.id===activeTopic}">${esc(i.name)}</button>`).join('');
 $('#civic-feed-status').textContent=feedError||'推薦隨每日資料更新'+(feed.updated?' · 最近檢查 '+new Date(feed.updated).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false}):' · 尚未取得新聞')+'；新增關鍵字於下次更新後取得推薦。';
 setLandmark(scope);
 const i=list.find(i=>i.id===activeTopic);
 if(!i){$('#civic-topics').innerHTML='<p class="civic-empty">這個範圍還沒有符合的議題。按「＋ 新增議題」，留下你想長期追蹤的方向。</p>';bindNavigation();return}
 const result=feed.results?.[i.id],recommendations=M.recommendations(i,result?.items||[],videos);
 const entries=[...(i.entries||[])].sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||''));
 const collected=new Map();for(const e of entries)for(const link of e.links||[]){const url=M.safeUrl(link.url);if(url&&!collected.has(url))collected.set(url,{...link,url,entry:e})}
 $('#civic-topics').innerHTML=`<div class="civic-topic" data-topic="${esc(i.id)}"><div class="civic-intro"><span class="civic-eyebrow">追蹤的入口</span><h3>${esc(i.name)}</h3><p>${esc(i.then||i.note||'哪些事件值得持續觀察？留下方向，讓來源與理解慢慢累積。')}</p><div class="meta"><span>${esc(i.scope)}</span><span>${esc(i.status)}</span><span>${(i.criteria||[]).length} 項追蹤指標</span><span>${esc(i.keys.join(' · '))}</span></div></div>${i.image?`<div class="civic-topic-image">${EntryImages.html({images:[i.image]})}</div>`:''}<div class="civic-paper"><div class="civic-observation-column"><div class="civic-understanding"><div class="civic-row"><h4>我的理解與追蹤方向</h4><button data-civic-edit="${esc(i.id)}">✎ 編輯</button></div><p>${esc(i.note||'還沒有留下自己的理解。按「編輯」整理你的觀察方向。')}</p><div class="civic-row civic-indicator-heading"><h4>觀察指標</h4><button data-civic-criterion-add="${esc(i.id)}">＋ 新增指標</button></div><ol class="civic-criteria">${(i.criteria||[]).map(c=>`<li><span>${esc(c.text)}</span><div class="civic-criterion-actions"><button data-civic-progress="${esc(c.id)}" data-owner="${esc(i.id)}">${esc(c.status)} · 記錄</button>${M.criterionRecords(i,c.id).length?`<button data-civic-criterion-records="${esc(c.id)}" data-owner="${esc(i.id)}">查看紀錄（${M.criterionRecords(i,c.id).length}）</button>`:''}<button data-civic-criterion-edit="${esc(c.id)}" data-owner="${esc(i.id)}">編輯</button><button data-civic-criterion-remove="${esc(c.id)}" data-owner="${esc(i.id)}" aria-label="移除指標：${esc(c.text)}">移除</button></div></li>`).join('')}</ol>${(i.criteria||[]).length?'':'<p class="muted">還沒有觀察指標，按「＋ 新增指標」留下你想追蹤的事項。</p>'}<p class="civic-disclaimer">「待查證」表示仍需要整理佐證，不代表事情尚未發生。</p></div><details class="civic-history" data-detail="timeline:${esc(i.id)}" ${opened.has('timeline:'+i.id)?'open':''}><summary>觀察紀錄（${entries.length}） · 展開時間軸</summary><div class="civic-actions"><button data-civic-entry="${esc(i.id)}">＋ 新增觀察</button></div>${entries.map(e=>`<div class="civic-entry" data-civic-record="${esc(e.id)}"><div class="meta"><time>${esc(e.date)}</time><span>${esc(e.label)}</span><button data-civic-entry="${esc(i.id)}" data-entry-id="${esc(e.id)}">編輯</button></div>${relationHtml(i,e)}${e.title?`<b>${esc(e.title)}</b>`:''}<p>${esc(e.text)}</p>${EntryImages.html(e)}${linksHtml(e.links)}</div>`).join('')||'<p class="muted">未來的消息、進展與判斷，依日期留在這裡。</p>'}</details></div><div class="civic-source-column"><div class="civic-row"><h4>從來源看這個議題</h4><button data-civic-entry="${esc(i.id)}">＋ 連結文章／影片</button></div><h5 class="civic-sources-heading">已收錄來源（${collected.size}）</h5><div class="civic-collected">${collected.size?[...collected.values()].map(link=>`<div class="civic-source"><div class="meta"><time>${esc(link.entry.date)}</time><span>${esc(link.entry.label)}</span></div><a href="${esc(link.url)}" target="_blank" rel="noopener noreferrer">↗ ${esc(link.title||link.url)}</a>${relationHtml(i,link.entry)}${EntryImages.html(link.entry)}${link.entry.text?`<blockquote>${esc(link.entry.text.slice(0,240))}${link.entry.text.length>240?'…':''}</blockquote>`:''}<button data-civic-entry="${esc(i.id)}" data-entry-id="${esc(link.entry.id)}">編輯來源與觀察</button></div>`).join(''):'<p class="civic-empty-sources">還沒有收錄來源。先留下值得回頭看的文章、影片與你的觀察。</p>'}</div><details class="civic-recommendations" data-detail="recommendations:${esc(i.id)}" ${opened.has('recommendations:'+i.id)?'open':''}><summary>推薦文章與影片（${recommendations.length}）<span>依關鍵字更新 · 展開挑選</span></summary><p class="muted">${result?.error?'本次新聞抓取失敗，保留先前推薦。':result?'來自公開新聞 RSS 與現有影片。':'等待下次更新後取得新聞，仍可自行新增來源。'}${result?.updated?' 新聞取得於 '+esc(date(result.updated))+'。':''} 推薦未經事實查核，不代表議題已有進展。</p>${recommendations.length?recommendations.map((item,index)=>`<div class="civic-recommendation"><div class="meta"><span>${esc(item.type||'文章')} · ${esc(item.source||'公開新聞')}</span><time>${Number.isFinite(Date.parse(item.published))?esc(date(item.published)):'日期未提供'}</time></div><a href="${esc(M.safeUrl(item.url))}" target="_blank" rel="noopener noreferrer">${esc(item.title)} ↗</a><button data-civic-collect="${index}" data-owner="${esc(i.id)}">＋ 收錄到記事</button></div>`).join(''):'<p class="muted">目前沒有符合關鍵字的推薦。</p>'}</details></div></div></div>`;
 bindNavigation();
 root.querySelectorAll('[data-civic-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.civicEdit));
 root.querySelectorAll('[data-civic-entry]').forEach(b=>b.onclick=()=>{editable(b.dataset.civicEntry);openEntry(b.dataset.civicEntry,b.dataset.entryId)});
 root.querySelectorAll('[data-civic-criterion-records]').forEach(b=>b.onclick=()=>showRecords(b.dataset.owner,b.dataset.civicCriterionRecords));
 root.querySelectorAll('[data-civic-progress]').forEach(b=>b.onclick=()=>openProgress(b.dataset.owner,b.dataset.civicProgress));
 root.querySelectorAll('[data-civic-criterion-add]').forEach(b=>b.onclick=()=>openCriterion(b.dataset.civicCriterionAdd));
 root.querySelectorAll('[data-civic-criterion-edit]').forEach(b=>b.onclick=()=>openCriterion(b.dataset.owner,b.dataset.civicCriterionEdit));
 root.querySelectorAll('[data-civic-criterion-remove]').forEach(b=>b.onclick=()=>{const item=topics().find(i=>i.id===b.dataset.owner),c=item?.criteria?.find(c=>c.id===b.dataset.civicCriterionRemove);if(!c)return;if(!confirm('移除「'+c.text+'」？\n既有觀察紀錄會保留。'))return;Object.assign(editable(item.id),M.removeCriterion(item,c.id));save();renderIssues()});
 root.querySelectorAll('[data-civic-collect]').forEach(b=>b.onclick=()=>{
  const item=editable(b.dataset.owner),recommendation=M.recommendations(item,feed.results?.[item.id]?.items||[],videos)[Number(b.dataset.civicCollect)];
  openEntry(item.id);$('#entry-note-title').value=recommendation.title;$('#entry-links').value=recommendation.title+' | '+recommendation.url;$('#entry-text').value='來源重點：\n\n與追蹤方向的關聯：';
 });
};
function showRecords(owner,id){const item=topics().find(i=>i.id===owner);if(!item)return;const ids=new Set(M.criterionRecords(item,id).map(e=>e.id));const history=root.querySelector('.civic-history');if(history)history.open=true;root.querySelectorAll('[data-civic-record]').forEach(el=>el.classList.toggle('civic-record-highlight',ids.has(el.dataset.civicRecord)));const first=[...root.querySelectorAll('[data-civic-record]')].find(el=>ids.has(el.dataset.civicRecord));first?.scrollIntoView({behavior:'smooth',block:'center'})}
let editingCriterion=null;
const criterionDialog=document.createElement('dialog');criterionDialog.id='civic-criterion-editor';criterionDialog.innerHTML=`<form id="civic-criterion-form"><h2 id="civic-criterion-heading">新增觀察指標</h2><label>指標內容<textarea id="civic-criterion-text" rows="4" maxlength="500" required placeholder="例如：提出包含離島、醫療、國防與民航的替代方案及成本"></textarea></label><p class="muted">一次新增一個指標。編輯文字會保留既有進度與觀察紀錄。</p><p id="civic-criterion-error" role="alert"></p><button id="civic-criterion-cancel" type="button">取消</button> <button type="submit">儲存指標</button></form>`;document.body.append(criterionDialog);
function openCriterion(owner,id=null){const item=topics().find(i=>i.id===owner),c=id?item?.criteria?.find(c=>c.id===id):null;if(!item||id&&!c)return;editingCriterion={owner,id};$('#civic-criterion-heading').textContent=id?'編輯觀察指標':'新增觀察指標';$('#civic-criterion-text').value=c?.text||'';$('#civic-criterion-error').textContent='';criterionDialog.showModal();$('#civic-criterion-text').focus()}
$('#civic-criterion-cancel').onclick=()=>criterionDialog.close();
$('#civic-criterion-form').onsubmit=e=>{e.preventDefault();try{const item=topics().find(i=>i.id===editingCriterion.owner);if(!item)throw Error('這個議題已不存在，請重新開啟。');const next=M.saveCriterion(item,$('#civic-criterion-text').value,editingCriterion.id,()=>crypto.randomUUID());Object.assign(editable(item.id),next);save();criterionDialog.close();renderIssues()}catch(error){$('#civic-criterion-error').textContent=error.message}};
let topicImage=null,topicImageBusy=false;
const imageField=document.createElement('fieldset');imageField.innerHTML=`<legend>議題圖片</legend><p class="muted">放一張位置圖、示意圖或相關照片，顯示在議題介紹下方。儲存同步後公開。</p><label>選擇圖片<input id="civic-image-file" type="file" accept="image/jpeg,image/png,image/webp"></label><label>或貼上圖片網址<input id="civic-image-url" type="url" placeholder="https://…"></label><label>圖片說明／來源<input id="civic-image-caption" maxlength="300"></label><div id="civic-image-preview"></div><button id="civic-image-remove" type="button">移除圖片</button><p id="civic-image-message" role="status" class="muted"></p>`;$('#civic-note').parentElement.before(imageField);
function showTopicImage(){const src=$('#civic-image-url').value.trim()||topicImage?.src;$('#civic-image-preview').innerHTML=src&&EntryImages.valid(src)?EntryImages.html({images:[{src,caption:$('#civic-image-caption').value}]}):'';$('#civic-image-remove').hidden=!src}
$('#civic-image-url').oninput=showTopicImage;$('#civic-image-caption').oninput=showTopicImage;
$('#civic-image-remove').onclick=()=>{topicImage=null;$('#civic-image-url').value='';$('#civic-image-caption').value='';$('#civic-image-file').value='';$('#civic-image-message').textContent='';showTopicImage()};
$('#civic-image-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;topicImageBusy=true;$('#civic-image-message').textContent='正在處理圖片…';try{topicImage={src:await EntryImages.compress(file)};$('#civic-image-url').value='';showTopicImage();$('#civic-image-message').textContent='圖片已加入，儲存議題後生效。'}catch(error){$('#civic-image-message').textContent=error.message}finally{topicImageBusy=false;e.target.value=''}};
function openEditor(id){editing=id||null;const i=id?topics().find(i=>i.id===id):null;topicImage=i?.image&&EntryImages.valid(i.image.src)?{...i.image}:null;$('#civic-image-file').value='';$('#civic-image-url').value=topicImage?.src?.startsWith('http')?topicImage.src:'';$('#civic-image-caption').value=topicImage?.caption||'';$('#civic-image-message').textContent='';showTopicImage();$('#civic-delete').hidden=!i;$('#civic-delete-message').textContent='';$('#civic-keyword-status').textContent='';$('#civic-editor-title').textContent=i?'編輯公共議題':'新增公共議題';$('#civic-name').value=i?.name||'';$('#civic-edit-scope').value=i?.scope||($('#civic-scope').value==='全部'?'中央':$('#civic-scope').value);$('#civic-keys').value=(i?.keys||[]).join(', ');$('#civic-note').value=i?.note||'';$('#civic-status').value=i?.status||'觀察中';$('#civic-editor').showModal()}
const keywordDialog=document.createElement('dialog');keywordDialog.id='civic-keyword-dialog';keywordDialog.innerHTML=`<div class="civic-keyword-head"><h2>推薦關鍵字</h2><button type="button" id="civic-keyword-close" aria-label="關閉關鍵字推薦">✕</button></div><p class="muted">依議題名稱、縣市與觀察方向整理搜尋詞，勾選適合的詞加入即可。</p><div id="civic-keyword-options"></div><p id="civic-keyword-error" role="status"></p><p class="muted">加入時保留原有關鍵字；儲存議題後才會同步。建議詞依詞彙規則產生，可自行調整。</p><button type="button" id="civic-apply-keywords">加入勾選的關鍵字</button>`;document.body.append(keywordDialog);
let keywordSuggestions=[];
$('#civic-suggest-keywords').onclick=()=>{
 try{keywordSuggestions=CivicKeywords.suggest({name:$('#civic-name').value,scope:$('#civic-edit-scope').value,note:$('#civic-note').value,criteria:(topics().find(i=>i.id===editing)?.criteria||[]).map(c=>c.text).join('\n')})}catch(error){$('#civic-keyword-status').textContent=error.message;$('#civic-name').focus();return}
 if(!keywordSuggestions.length){$('#civic-keyword-status').textContent='請使用較具體的議題名稱，或自行填寫關鍵字。';return}
 $('#civic-keyword-options').innerHTML=keywordSuggestions.map((item,index)=>`<label class="civic-keyword-choice"><input type="checkbox" value="${index}" checked><span><b>${esc(item.term)}</b><small>${esc(item.reason)}</small></span></label>`).join('');$('#civic-keyword-error').textContent='';keywordDialog.showModal();
};
$('#civic-keyword-close').onclick=()=>keywordDialog.close();
$('#civic-apply-keywords').onclick=()=>{const selected=[...$('#civic-keyword-options').querySelectorAll('input:checked')].map(input=>keywordSuggestions[Number(input.value)].term);if(!selected.length){$('#civic-keyword-error').textContent='請至少勾選一個建議詞。';return}$('#civic-keys').value=CivicKeywords.mergeKeywords($('#civic-keys').value,selected);$('#civic-keyword-status').textContent='已合併 '+selected.length+' 個勾選建議，保留原有關鍵字；可再自行調整。';keywordDialog.close()};
$('#civic-add').onclick=()=>openEditor();$('#civic-cancel').onclick=()=>$('#civic-editor').close();
$('#civic-delete').onclick=()=>{
 const item=issues.find(i=>i.id===editing);
 if(!item){$('#civic-delete-message').textContent='請先完成 GitHub 議題同步，再刪除這個議題。';return}
 if(!confirm('確定刪除「'+item.name+'」？\n此議題的指標、記事與已收錄來源會移除；同時關聯其他議題的記事會保留。\n同步後其他裝置也會更新。'))return;
 deletedFallbacks.add(item.id);localStorage.setItem('civic-deleted-topics',JSON.stringify([...deletedFallbacks]));
 issues=M.removeTopic(issues,item.id);if(selected?.id===item.id)selected=null;if(activeTopic===item.id)activeTopic=null;
 if(localStorage.getItem('civic-selected-topic')===item.id)localStorage.removeItem('civic-selected-topic');
 editing=null;save();$('#civic-editor').close();renderIssues();renderNews();
};
$('#civic-form').onsubmit=e=>{e.preventDefault();const keys=$('#civic-keys').value.split(/[,，]/).map(s=>s.trim()).filter(Boolean),name=$('#civic-name').value.trim();if(!name||!keys.length)return;if(topicImageBusy){$('#civic-image-message').textContent='圖片仍在處理中，請稍候再儲存。';return}const imageSrc=$('#civic-image-url').value.trim()||topicImage?.src;if(imageSrc&&!EntryImages.valid(imageSrc)){$('#civic-image-message').textContent='請輸入有效的 http 或 https 圖片網址。';return}const image=imageSrc?{src:imageSrc,caption:$('#civic-image-caption').value.trim()}:null;const candidate=JSON.parse(JSON.stringify(issues));const testIssue=candidate.find(x=>x.id===editing);if(testIssue)testIssue.image=image;else candidate.push({image});if(new TextEncoder().encode(JSON.stringify(candidate,null,2)).length>850000){$('#civic-image-message').textContent='圖片已接近同步容量，請改用圖片網址。';return}const i=editing?editable(editing):{id:crypto.randomUUID(),kind:'civic',entries:[],criteria:[],then:''};Object.assign(i,{image,name,scope:$('#civic-edit-scope').value,keys,note:$('#civic-note').value.trim(),status:$('#civic-status').value});if(!editing)issues.push(i);activeTopic=i.id;$('#civic-scope').value=i.scope;localStorage.setItem('civic-selected-scope',i.scope);save();$('#civic-editor').close();renderIssues();};
const dialog=document.createElement('dialog');dialog.id='civic-progress-editor';dialog.innerHTML=`<form id="civic-progress-form"><h2>記錄指標進展</h2><p id="civic-progress-title"></p><p class="muted">儲存後會更新指標狀態，並新增一篇記事到本議題的「觀察紀錄」。</p><label>狀態<select id="civic-progress-state">${M.states.map(s=>option(s)).join('')}</select></label><label>日期<input id="civic-progress-date" type="date" required></label><label>觀察與依據<textarea id="civic-progress-note" rows="3"></textarea></label><label>佐證連結（每行：名稱 | 網址；已達成需附連結或圖片）<textarea id="civic-progress-links" rows="3"></textarea></label><p id="civic-progress-error" role="alert"></p><button type="button" id="civic-progress-cancel">取消</button> <button type="submit">儲存進展</button></form>`;document.body.append(dialog);
const progressImages=EntryImages.createEditor({prefix:'civic-progress',contentId:'civic-progress-note',beforeId:'civic-progress-links',imageLabel:'佐證圖片',contentLabel:'觀察與依據'});progressImages.mount();
function openProgress(id,cid){progress={id,cid};progressImages.reset();const c=topics().find(i=>i.id===id).criteria.find(c=>c.id===cid);$('#civic-progress-title').textContent=c.text;$('#civic-progress-state').value=c.status;$('#civic-progress-date').value=today();$('#civic-progress-note').value='';$('#civic-progress-links').value='';$('#civic-progress-error').textContent='';dialog.showModal()}
$('#civic-progress-cancel').onclick=()=>dialog.close();
$('#civic-progress-form').onsubmit=e=>{e.preventDefault();let images;try{images=progressImages.get()}catch(error){$('#civic-progress-error').textContent=error.message;return}const links=[];for(const line of $('#civic-progress-links').value.split('\n').filter(s=>s.trim())){const pos=line.indexOf('|'),url=M.safeUrl((pos<0?line:line.slice(pos+1)).trim());if(!url){$('#civic-progress-error').textContent='請輸入有效的 http 或 https 來源連結。';return}links.push({title:pos<0?url:line.slice(0,pos).trim()||url,url})}const note=$('#civic-progress-note').value.trim();if(!note&&!images.length&&!links.length){$('#civic-progress-error').textContent='請填寫觀察文字，或附上圖片、來源連結。';return}const status=$('#civic-progress-state').value;if(status==='已達成'&&!links.length&&!images.length){$('#civic-progress-error').textContent='標記已達成前，請附至少一個佐證連結或圖片。';return}const item=topics().find(i=>i.id===progress.id),criterion=item?.criteria?.find(c=>c.id===progress.cid);if(!criterion){$('#civic-progress-error').textContent='指標已不存在，請重新開啟。';return}const entry={id:crypto.randomUUID(),issueIds:[item.id],date:$('#civic-progress-date').value,createdAt:new Date().toISOString(),label:'進度紀錄',criterionId:criterion.id,criterionText:criterion.text,title:criterion.text,text:criterion.status+' → '+status+'\n'+note,links,images,country:'tw',region:'asia'};const candidate=structuredClone(issues),check=candidate.find(i=>i.id===item.id);if(check)check.entries.push(entry);else candidate.push({...structuredClone(item),entries:[...(item.entries||[]),entry]});if(new TextEncoder().encode(JSON.stringify(candidate,null,2)).length>850000){$('#civic-progress-error').textContent='圖片已接近同步容量，請改用圖片網址。';return}const i=editable(item.id),c=i.criteria.find(c=>c.id===progress.cid);c.status=status;c.updatedAt=new Date().toISOString();i.entries.push(entry);save();dialog.close();renderIssues();showRecords(i.id,c.id)};
function ensureScopeVisible(){const nav=$('#civic-city-tabs'),active=nav.querySelector('[aria-pressed="true"]');if(active&&nav.scrollWidth>nav.clientWidth){const a=active.getBoundingClientRect(),n=nav.getBoundingClientRect();if(a.left<n.left)nav.scrollLeft+=a.left-n.left-8;else if(a.right>n.right)nav.scrollLeft+=a.right-n.right+8}}
window.addEventListener('resize',()=>requestAnimationFrame(ensureScopeVisible));
function selectScope(scope){$('#civic-scope').value=scope;localStorage.setItem('civic-selected-scope',scope);activeTopic=null;window.renderCivic()}
function bindNavigation(){root.querySelectorAll('[data-civic-city]').forEach(b=>b.onclick=()=>selectScope(b.dataset.civicCity));root.querySelectorAll('[data-civic-topic]').forEach(b=>b.onclick=()=>{activeTopic=b.dataset.civicTopic;window.renderCivic()})}
function setLandmark(scope){root.style.setProperty('--civic-landmark-position',['臺北市','高雄市','嘉義市'].includes(scope)?'center top':'center center');const credit=M.landmark(scope,landmarks);root.style.setProperty('--civic-landmark',credit?'url("'+credit.file+'")':'none');$('#civic-landmark-credit').innerHTML=credit?`${esc(credit.name)} · <a href="${esc(credit.source)}" target="_blank" rel="noopener noreferrer">${esc(credit.author)}</a> · <a href="${esc(M.safeUrl(credit.licenseUrl)||credit.source)}" target="_blank" rel="noopener noreferrer">${esc(credit.license)}</a> · 裁切淡化`:''}
fetch('landmarks/credits.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{landmarks=data;setLandmark($('#civic-scope').value)}).catch(()=>{});
$('#civic-scope').onchange=()=>selectScope($('#civic-scope').value);$('#civic-search').oninput=window.renderCivic;
$('#civic-sync-settings').onclick=()=>$('#sync-settings').click();
const syncStatus=()=>{$('#civic-sync-status').textContent=$('#sync-message').textContent||'編輯先存於本機；設定 GitHub 權杖後自動同步。'};
new MutationObserver(syncStatus).observe($('#sync-message'),{childList:true,subtree:true,characterData:true});syncStatus();
let loading=false;
window.loadCivicRecommendations=async()=>{if(loading)return;loading=true;try{const r=await fetch('public-news.json?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data.topics)||!data.results)throw Error();feed=data;feedError=''}catch{feedError='新聞推薦暫時讀取失敗；保留已載入的內容。請按上方「重新載入頁面資料」重試。'}finally{loading=false;window.renderCivic()}};
window.renderCivic();window.loadCivicRecommendations();
})();
